//An electricity department wants to automate monthly bill calculation for multiple consumers.
//Write a C program that:
//Accepts the number of consumers.
//For each consumer, accepts the number of units consumed.
//Calculates the bill according to the following slabs:
//Units    Rates
//0-100    ₹2/unit
//101-200  ₹3/unit
//201-300  ₹5/unit
//Above 300 ₹7/unit

//Displays the bill for each consumer.
//Calculates the total revenue generated by the department.
#include<stdio.h>
int main(){
    int n,units,bill;
    int total_revenue=0;
printf("Enter the number of consumers:");
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        printf("enter the number of units consumed by %d:",i);
        scanf("%d",&units);
        if(units<=100){
            bill= units*2;
        }else if(units<=200){
            bill=100*2 + (units-100)*3;
        }else if(units<=300){
             bill=100*2 + 100*3+(units-200)*5;
        }else{
            bill=100*2 + 100*3+ 100*5 +(units-300)*7;
        }
        
        printf("consumer %d bill= Rs.%d \n",i,bill);
      total_revenue=total_revenue+bill;
    }
    printf("total revenue generated by deprtment:%d",total_revenue);
    return 0;
}
